function Root(){const[session,setSession]=useState<any>();useEffect(()=>{supabase.auth.getSession().then(({data})=>setSession(data.session));return supabase.auth.onAuthStateChange((_e,s)=>setSession(s)).data.subscription.unsubscribe()},[]);return session?<Home/>:<Login onSuccess={setSession}/>}createRoot(document.getElementById('root')!).render(<Root/>);
